#!/usr/bin/env python3
import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

ROOT = Path('/root')
THERAPY_CATALOG_PATH = ROOT / 'therapy_catalog.json'
BAG_SUPPLY_COST_PATH = ROOT / 'bag_supply_cost.csv'
DELIVERY_PAYMENT_PATH = ROOT / 'delivery_payment.csv'
PATIENT_OVERRIDES_PATH = ROOT / 'patient_overrides.csv'
ANALYSIS_PATH = ROOT / 'infusion_batch_analysis.json'
SUMMARY_PATH = ROOT / 'infusion_batch_summary.md'

ASSUMPTIONS = {
    'currency': 'USD',
    'days_per_delivery_7_day': 7,
    'deliveries_per_year_7_day': 52,
    'days_per_delivery_14_day': 14,
    'deliveries_per_year_14_day': 26,
    'decision_threshold_usd': 15000,
}

CURRENCY_FIELDS = {
    'drug_cost_per_1000_mg_usd',
    'bag_supply_cost_usd',
    'payment_per_delivery_per_patient_usd',
    'annual_drug_cost_7_day_usd',
    'annual_supply_cost_7_day_usd',
    'annual_revenue_7_day_usd',
    'annual_margin_7_day_usd',
    'annual_drug_cost_14_day_usd',
    'annual_supply_cost_14_day_usd',
    'annual_revenue_14_day_usd',
    'annual_margin_14_day_usd',
    'annual_margin_difference_14_minus_7_usd',
    'total_annual_margin_7_day_usd',
    'total_annual_margin_14_day_usd',
    'total_annual_margin_difference_14_minus_7_usd',
    'absolute_total_margin_difference_usd',
}


def money(value):
    """Round a numeric value to 2 decimal places and return a JSON number."""
    return float(Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))


def dec(value):
    return Decimal(str(value))


def is_included(value):
    if value is True:
        return True
    if isinstance(value, str):
        return value.strip().lower() == 'true'
    return False


def load_csv_rows(path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def load_in_scope_therapies(catalog):
    therapies = []
    for service_line in catalog.get('service_lines', []):
        for therapy in service_line.get('therapies', []):
            if is_included(therapy.get('include_in_review')):
                therapies.append(dict(therapy))
    therapies.sort(key=lambda item: item['therapy_code'])
    return therapies


def build_label_lookup(therapies):
    lookup = {}
    for therapy in therapies:
        labels = [therapy['therapy_name']] + list(therapy.get('aliases') or [])
        for label in labels:
            if label in lookup and lookup[label]['therapy_code'] != therapy['therapy_code']:
                raise ValueError(f"Label {label!r} maps to multiple therapies")
            lookup[label] = therapy
    return lookup


def resolve_payments(delivery_rows, label_lookup, therapies):
    payments = {}
    for row in delivery_rows:
        therapy = label_lookup.get(row['therapy_label'])
        if therapy is None:
            continue
        therapy_code = therapy['therapy_code']
        if therapy_code in payments:
            raise ValueError(f"Multiple delivery payment rows matched in-scope therapy {therapy_code}")
        payments[therapy_code] = dec(row['payment_per_delivery_per_patient_usd'])

    missing = [t['therapy_code'] for t in therapies if t['therapy_code'] not in payments]
    if missing:
        raise ValueError(f"Missing delivery payment for in-scope therapies: {', '.join(missing)}")
    return payments


def resolve_active_patients(patient_rows, therapies):
    in_scope_codes = {therapy['therapy_code'] for therapy in therapies}
    approved_latest = {}
    for row in patient_rows:
        if row['status'] != 'approved':
            continue
        therapy_code = row['therapy_code']
        if therapy_code not in in_scope_codes:
            continue
        revision = int(row['revision'])
        current = approved_latest.get(therapy_code)
        if current is None or revision > int(current['revision']):
            approved_latest[therapy_code] = row

    missing = [therapy['therapy_code'] for therapy in therapies if therapy['therapy_code'] not in approved_latest]
    if missing:
        raise ValueError(f"Missing approved active patient override for in-scope therapies: {', '.join(missing)}")

    return {code: int(row['active_patients']) for code, row in approved_latest.items()}


def validate_output(analysis):
    expected_assumptions = {
        'currency',
        'days_per_delivery_7_day',
        'deliveries_per_year_7_day',
        'days_per_delivery_14_day',
        'deliveries_per_year_14_day',
        'decision_threshold_usd',
    }
    if set(analysis['assumptions']) != expected_assumptions:
        raise AssertionError('assumptions block does not have exactly the expected 6 keys')
    if analysis['assumptions'] != ASSUMPTIONS:
        raise AssertionError('assumptions block has incorrect values')

    therapy_codes = [therapy['therapy_code'] for therapy in analysis['therapies']]
    if therapy_codes != sorted(therapy_codes):
        raise AssertionError('therapies are not sorted by therapy_code')

    for therapy in analysis['therapies']:
        for key, value in therapy.items():
            if key in CURRENCY_FIELDS and dec(value) != dec(value).quantize(Decimal('0.01')):
                raise AssertionError(f'{therapy["therapy_code"]}.{key} is not rounded to 2 decimals')

    expected_totals = {
        'total_annual_margin_7_day_usd',
        'total_annual_margin_14_day_usd',
        'total_annual_margin_difference_14_minus_7_usd',
        'absolute_total_margin_difference_usd',
    }
    if set(analysis['totals']) != expected_totals:
        raise AssertionError('totals block does not have exactly the expected 4 keys')
    if set(analysis['recommendation']) != {'decision', 'justification'}:
        raise AssertionError('recommendation block must have decision and justification')

    per_therapy_diff_sum = money(sum(dec(t['annual_margin_difference_14_minus_7_usd']) for t in analysis['therapies']))
    total_diff = analysis['totals']['total_annual_margin_difference_14_minus_7_usd']
    if dec(per_therapy_diff_sum) != dec(total_diff):
        raise AssertionError('total margin difference does not equal sum of per-therapy differences')

    absolute_diff = analysis['totals']['absolute_total_margin_difference_usd']
    if dec(absolute_diff) != abs(dec(total_diff)):
        raise AssertionError('absolute total margin difference is incorrect')

    expected_decision = 'move_to_14_day' if dec(absolute_diff) < dec(ASSUMPTIONS['decision_threshold_usd']) else 'keep_7_day'
    if analysis['recommendation']['decision'] != expected_decision:
        raise AssertionError('decision rule was not correctly applied')


def main():
    with THERAPY_CATALOG_PATH.open() as f:
        catalog = json.load(f)

    bag_rows = load_csv_rows(BAG_SUPPLY_COST_PATH)
    delivery_rows = load_csv_rows(DELIVERY_PAYMENT_PATH)
    patient_rows = load_csv_rows(PATIENT_OVERRIDES_PATH)

    therapies = load_in_scope_therapies(catalog)
    label_lookup = build_label_lookup(therapies)
    payments = resolve_payments(delivery_rows, label_lookup, therapies)
    active_patients_by_code = resolve_active_patients(patient_rows, therapies)
    bag_supply_cost_by_size = {
        int(row['bag_size_ml']): dec(row['bag_supply_cost_usd'])
        for row in bag_rows
    }

    therapy_outputs = []
    for therapy in therapies:
        therapy_code = therapy['therapy_code']
        active_patients = active_patients_by_code[therapy_code]
        drug_cost_per_1000_mg = dec(therapy['drug_cost_per_1000_mg_usd'])
        dose_mg_per_day = dec(therapy['dose_mg_per_day'])
        bag_size_ml = int(therapy['bag_size_ml'])
        if bag_size_ml not in bag_supply_cost_by_size:
            raise ValueError(f'Missing bag supply cost for bag size {bag_size_ml}')
        bag_supply_cost = bag_supply_cost_by_size[bag_size_ml]
        payment = payments[therapy_code]
        active_patients_dec = dec(active_patients)

        annual_drug_cost_7 = drug_cost_per_1000_mg * active_patients_dec * dose_mg_per_day * dec(ASSUMPTIONS['days_per_delivery_7_day']) * dec(ASSUMPTIONS['deliveries_per_year_7_day']) / dec(1000)
        annual_supply_cost_7 = bag_supply_cost * active_patients_dec * dec(ASSUMPTIONS['deliveries_per_year_7_day'])
        annual_revenue_7 = payment * active_patients_dec * dec(ASSUMPTIONS['deliveries_per_year_7_day'])
        annual_margin_7 = annual_revenue_7 - annual_drug_cost_7 - annual_supply_cost_7

        annual_drug_cost_14 = drug_cost_per_1000_mg * active_patients_dec * dose_mg_per_day * dec(ASSUMPTIONS['days_per_delivery_14_day']) * dec(ASSUMPTIONS['deliveries_per_year_14_day']) / dec(1000)
        annual_supply_cost_14 = bag_supply_cost * active_patients_dec * dec(ASSUMPTIONS['deliveries_per_year_14_day'])
        annual_revenue_14 = payment * active_patients_dec * dec(ASSUMPTIONS['deliveries_per_year_14_day'])
        annual_margin_14 = annual_revenue_14 - annual_drug_cost_14 - annual_supply_cost_14
        annual_margin_difference = annual_margin_14 - annual_margin_7

        therapy_outputs.append({
            'therapy_code': therapy_code,
            'therapy_name': therapy['therapy_name'],
            'active_patients': active_patients,
            'drug_cost_per_1000_mg_usd': money(drug_cost_per_1000_mg),
            'dose_mg_per_day': int(therapy['dose_mg_per_day']),
            'bag_size_ml': bag_size_ml,
            'bag_supply_cost_usd': money(bag_supply_cost),
            'payment_per_delivery_per_patient_usd': money(payment),
            'annual_drug_cost_7_day_usd': money(annual_drug_cost_7),
            'annual_supply_cost_7_day_usd': money(annual_supply_cost_7),
            'annual_revenue_7_day_usd': money(annual_revenue_7),
            'annual_margin_7_day_usd': money(annual_margin_7),
            'annual_drug_cost_14_day_usd': money(annual_drug_cost_14),
            'annual_supply_cost_14_day_usd': money(annual_supply_cost_14),
            'annual_revenue_14_day_usd': money(annual_revenue_14),
            'annual_margin_14_day_usd': money(annual_margin_14),
            'annual_margin_difference_14_minus_7_usd': money(annual_margin_difference),
        })

    total_margin_7 = money(sum(dec(therapy['annual_margin_7_day_usd']) for therapy in therapy_outputs))
    total_margin_14 = money(sum(dec(therapy['annual_margin_14_day_usd']) for therapy in therapy_outputs))
    total_difference = money(sum(dec(therapy['annual_margin_difference_14_minus_7_usd']) for therapy in therapy_outputs))
    absolute_difference = money(abs(dec(total_difference)))

    decision = 'move_to_14_day' if dec(absolute_difference) < dec(ASSUMPTIONS['decision_threshold_usd']) else 'keep_7_day'
    justification = (
        f"Absolute total margin difference is ${absolute_difference:,.2f}, "
        f"compared with the ${ASSUMPTIONS['decision_threshold_usd']:,.2f} threshold; decision is {decision}."
    )

    analysis = {
        'assumptions': ASSUMPTIONS,
        'therapies': therapy_outputs,
        'totals': {
            'total_annual_margin_7_day_usd': total_margin_7,
            'total_annual_margin_14_day_usd': total_margin_14,
            'total_annual_margin_difference_14_minus_7_usd': total_difference,
            'absolute_total_margin_difference_usd': absolute_difference,
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    validate_output(analysis)

    with ANALYSIS_PATH.open('w') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# Infusion Batch Analysis Summary',
        f"Total 7-day margin (USD): {total_margin_7:.2f}",
        f"Total 14-day margin (USD): {total_margin_14:.2f}",
        f"Absolute difference (USD): {absolute_difference:.2f}",
        f"Decision: {decision}",
        justification,
    ]
    SUMMARY_PATH.write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

